{
  "reply": "Here are the inferred rules to sort your invoices and protect your existing filters.",
  "proposed_rules": [
    {
      "name": "Northwind Invoices",
      "match_mode": "all",
      "conditions": [
        {
          "field": "from",
          "op": "contains",
          "value": "northwind-analytics"
        },
        {
          "field": "subject",
          "op": "contains",
          "value": "Invoice"
        }
      ],
      "actions": {
        "move_to": "Invoices",
        "mark_read": false,
        "flag": false
      },
      "placement": "top",
      "rationale": "Catches specific sender invoices before general rules."
    },
    {
      "name": "General Invoices",
      "match_mode": "any",
      "conditions": [
        {
          "field": "subject",
          "op": "contains",
          "value": "Invoice"
        },
        {
          "field": "subject",
          "op": "contains",
          "value": "Receipt"
        }
      ],
      "actions": {
        "move_to": "Invoices",
        "mark_read": false,
        "flag": false
      },
      "placement": "bottom",
      "rationale": "Catches invoices from other senders or with 'Receipt' in subject."
    }
  ]
}

